  const lens=(x,y=210,diverging=false)=>path(diverging?`M${x-14},${y-85} Q${x+4},${y} ${x-14},${y+85} L${x+14},${y+85} Q${x-4},${y} ${x+14},${y-85} Z`:`M${x},${y-85} Q${x+35},${y} ${x},${y+85} Q${x-35},${y} ${x},${y-85} Z`,C.cyan,2,'#153c50');
  const mirror=(x,y=210,convex=false)=>path(`M${x},${y-86} Q${x+(convex?-35:35)},${y} ${x},${y+86}`,C.ink,6)+label(x,y+112,convex?'convex mirror':'concave mirror');
  const rail=()=>rect(55,337,690,20,'#293f52')+line(55,210,745,210,'#486679',1,'6 7')+label(105,235,'axis');
  function optical(s,{f=15,U=40,screen=24,mirrorMode=false,allowVirtual=false,name='Optical bench'}={}) {
    const x=mirrorMode?650:370,k=mirrorMode?5:4,dir=mirrorMode?-1:1,V=Math.abs(U-f)<.001?null:f*U/(U-f),obj=x-U*k,scr=x+dir*screen*k,y=210;
    let b=rail()+arrow(obj,y,45)+label(obj,280,'LED object')+line(obj,y,obj,337,C.line,2);
    if(s.step>=1)b+=(mirrorMode?mirror(x):lens(x))+line(x,295,x,337,C.line,2)+circle(x+dir*f*k,y,4,C.gold)+label(x+dir*f*k,y+23,'F');
    if(s.step>=2)b+=line(scr,112,scr,310,C.muted,7)+line(scr,310,scr,337,C.line,3)+label(scr,95,'movable screen');
    if(s.step>=3&&V===null)b+=line(obj,165,x,165,C.gold,2)+line(obj,165,x,y,C.cyan,2)+line(x,165,x+dir*240,165+240*45/(f*k),C.gold,2)+line(x,y,x+dir*240,y+240*45/(f*k),C.cyan,2);
    if(s.step>=3&&V!==null){const ix=x+dir*V*k,iy=y+45*V/U;
      b+=line(obj,165,x,165,C.gold,2)+line(obj,165,x,y,C.cyan,2);
      if(V>0){b+=line(x,165,ix,iy,C.gold,2)+line(x,y,ix,iy,C.cyan,2);if(Math.abs(screen-V)<1.2)b+=arrow(scr,y,-45*V/U,C.green);else b+=`<ellipse cx="${scr}" cy="${y+20}" rx="8" ry="${Math.min(60,8+Math.abs(screen-V)*3)}" fill="#ffd166" opacity=".22"/>`;}
      else if(allowVirtual){const end=x+dir*90*k;b+=line(x,165,end,165+(end-x)*(iy-165)/(ix-x),C.gold,2)+line(x,y,end,y+(end-x)*(iy-y)/(ix-x),C.cyan,2)+line(x,165,ix,iy,C.gold,2,'6 6')+line(x,y,ix,iy,C.cyan,2,'6 6')+arrow(ix,y,-45*V/U,C.green)+label(Math.max(90,Math.min(710,ix)),100,'virtual image · no screen image');}
    }
    b+=text(400,385,`U = ${U} cm · screen = ${screen} cm · ${V===null?'image at infinity':V>0?(Math.abs(screen-V)<1.2?'sharp real image':'move screen for focus'):'virtual: observe by looking through the optic'}`,14,C.cyan);
    return base(name,b,'Positive U,V magnitudes for real conjugates · paraxial rays · secure glass; never use the Sun');
  }
