  function prismData(v){const i=N(v,'incidence',49),n=N(v,'index',1.5),A=60,r1=Math.asin(Math.sin(i*Math.PI/180)/n),r2=A*Math.PI/180-r1,q=n*Math.sin(r2),tir=q>1,e=tir?null:Math.asin(q)*180/Math.PI;return{i,n,A,r1,r2,e,tir,deviation:tir?null:i+e-A,min:2*Math.asin(n*.5)*180/Math.PI-A};}
